SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(d),'identity',to_jsonb(pg_identify_object(d.classoid,d.objoid,0))) ORDER BY d.classoid,d.objoid),'[]'::jsonb) AS payload FROM pg_shdescription d WHERE d.classoid='pg_authid'::regclass OR (d.classoid='pg_database'::regclass AND d.objoid=(SELECT oid FROM pg_database WHERE datname=current_database()))) AS capture